import tarfile,sys,json,hashlib
from pathlib import Path
p=Path(sys.argv[1]);results=[]
with tarfile.open(p/'source.tar.gz','r:gz') as archive:
 for extraction in ['source','source-repro']:
  mismatches=[];compared=0
  for member in archive.getmembers():
   if member.isfile():
    expected=archive.extractfile(member).read();actual=(p/extraction/member.name).read_bytes();compared+=1
    if expected!=actual:mismatches.append(member.name)
  results.append({'extraction':extraction,'original_regular_files_compared':compared,'mismatches':mismatches})
assert all(r['original_regular_files_compared']>0 and not r['mismatches'] for r in results)
print(json.dumps(results,indent=2))

import sys,hashlib,zipfile,json
from pathlib import Path
p,site=map(Path,sys.argv[1:3]);wheel=p/'urllib3-2.8.0-py3-none-any.whl';compared=[];mismatches=[]
with zipfile.ZipFile(wheel) as z:
 for n in z.namelist():
  if n.endswith('.py'):
   compared.append(n)
   if not (site/n).is_file() or (site/n).read_bytes()!=z.read(n):mismatches.append(n)
print(json.dumps({'artifact':wheel.name,'artifact_sha256':hashlib.sha256(wheel.read_bytes()).hexdigest(),'python_sources_compared':len(compared),'mismatches':mismatches},indent=2))
assert compared and not mismatches

import sys,json,re,importlib.metadata as m
from pathlib import Path
p=Path(sys.argv[1]);versions={}
for name,version in re.findall(r'(?m)^([a-zA-Z0-9_.-]+)==([^\n]+)',(p/'candidate.lock').read_text()):
 versions[re.sub(r'[-_.]+','-',name).lower()]=version.rstrip(' \\')
versions['openhands-sdk']=versions['openhands-tools']='1.50.0'
mismatches=[]
for name,expected in versions.items():
 actual=m.version(name)
 if actual!=expected:mismatches.append({'name':name,'expected':expected,'actual':actual})
print(json.dumps({'checked_requirement_versions':len(versions),'installed_distributions':len(list(m.distributions())),'mismatches':mismatches},indent=2))
assert len(versions)==176 and not mismatches
